<template><view class="page"><text class="title">隐私与授权</text><text class="sub">管理家庭成员可查看的信息范围</text><view class="card"><view v-for="item in items" :key="item.key" class="row"><view><text class="name">{{item.name}}</text><text class="desc">{{item.desc}}</text></view><switch :checked="item.enabled" color="#326a53" @change="e=>item.enabled=e.detail.value"/></view></view><view class="tip">健康与紧急信息仅用于家庭照护演示，当前数据均为本地测试数据。</view></view></template><script>export default{data(){return{items:[{key:'health',name:'健康数据授权',desc:'允许家庭成员查看健康趋势',enabled:true},{key:'location',name:'位置状态授权',desc:'允许查看在家/外出状态',enabled:true},{key:'activity',name:'活动记录授权',desc:'允许查看日常活动摘要',enabled:true},{key:'service',name:'服务订单共享',desc:'家庭成员可查看养老服务订单',enabled:false}]} }}</script><style scoped>.page{min-height:100vh;padding:30rpx;background:#f6f7f3}.title{display:block;font-size:40rpx;font-weight:900;color:#2d4338}.sub{display:block;margin:10rpx 0 28rpx;color:#7b857f}.card{padding:0 24rpx;background:#fff;border-radius:28rpx}.row{min-height:116rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid #edf0ec}.name,.desc{display:block}.name{font-size:25rpx;font-weight:800}.desc{margin-top:6rpx;color:#858e88;font-size:19rpx}.tip{margin-top:24rpx;padding:24rpx;border-radius:22rpx;background:#eef3ed;color:#718078;font-size:21rpx;line-height:1.7}</style>